// ProveContract runs every check — the generated ones and any you
// wrote — against the deliberately broken implementation it names, and
// fails if the check does not catch it.
//
//	func TestMyChecksCanFail(t *testing.T) {
//		ProveContract(t, ContractHarness[*InMemory]{Name: "in-memory", New: NewInMemory}, myChecks)
//	}
//
// A check that always passes is indistinguishable from a working one
// until something breaks in production. This is what tells them apart:
// give each check a ProvenBy, and this proves the check can fail.
//
// A check with no ProvenBy is not ignored — it has to say why, in
// Argued. The two are held level in both directions: claiming proof
// without a broken implementation fails here, and supplying one for a
// check that claims nothing fails too.
//
// It takes the same arguments RunContract does, and for one reason: a
// check may need a capability, and the answer is a fact about this
// interface rather than about any one implementation. The harness is
// where you write it once. A planted defect stands in for a real
// subject, so it borrows the same answer rather than being asked for one
// of its own — which nothing here could supply.
func ProveContract(
	t *testing.T, opts ...ContractRunOpt,
) {
	t.Helper()
	var rc contractRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	// The RUN's config, not the derived one: a check proven at default
	// pools carries no evidence about the pools a run actually uses.
	fx := contractNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "ProveContract")
	s := contractSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	// Read off the subjects, because a door is answered once for the
	// interface and every subject of it reads the same answer.
	doors := suite.Doors(rc.Subjects...)
	defects := contractProofs()
	for _, row := range rc.rows {
		if row.ProvenBy == nil {
			continue
		}
		bd, err := row.bind(fx)
		if err != nil {
			t.Fatalf("ProveContract: %v", err)
		}
		sub, err := row.ProvenBy.Subject()
		if err != nil {
			t.Fatalf("ProveContract: check %q: defect: %v", bd.ID, err)
		}
		defects[bd.ID] = prove.Defect[Contract]{
			Subject: sub, Reason: row.ProvenReason,
		}
	}
	// A declined check takes its proof with it: proving a row the run was
	// told to leave out reports on a claim this package no longer makes,
	// and the parity gate fails naming a check the set does not hold.
	for _, id := range rc.Drops {
		delete(defects, id)
	}
	prove.All(t, s.Checks, defects.Answering(doors))
}

// GreenContract runs every check — the generated ones and any you
// wrote — against an implementation that is CORRECT but different, and
// fails if a check rejects it.
//
//	func TestAnotherPolicyIsAllowed(t *testing.T) {
//		GreenContract(t, suite.Subject[Contract]{
//			Name: "evicts the newest", New: newNewestFirst,
//		})
//	}
//
// ProveContract measures whether these checks can fire. This measures
// whether they fire SELECTIVELY. Nothing else here can tell a check that
// is right from one that is too strong: a check forbidding something the
// declaration permits looks exactly like a suite working, until somebody
// writes a legal implementation and it fails.
//
// The control is a real alternative, not a broken one — a different
// eviction victim, a delivery that duplicates where the contract allows
// it, a lazier evaluation behind the same boundary. Where a check
// genuinely cannot apply to your control, put its ID in the subject's
// Excused map: an excused check is skipped by name, because it yields no
// evidence either way.
//
// Same arguments as RunContract, so the control meets the checks
// the run does — including the ones you wrote, which no caller can bind
// for themselves.
func GreenContract(
	t *testing.T,
	control suite.Subject[Contract],
	opts ...ContractRunOpt,
) {
	t.Helper()
	var rc contractRunConfig
	for _, o := range opts {
		o.applyTo(&rc)
	}
	fx := contractNewFixture()
	for _, row := range rc.rows {
		rc.AddCheck(row.bind(fx))
	}
	rc.Fail(t, "GreenContract")
	s := contractSuite(fx).With(rc.Extra...).Without(rc.Drops...)
	// The doors the run answers, so a control is refused for being wrong
	// rather than for being unwired — a wiring red recorded as "the suite
	// rejected correct code" would poison the measurement it exists for.
	for door, answer := range suite.Doors(rc.Subjects...) {
		if control.Provides == nil {
			control.Provides = map[suite.Capability]any{}
		}
		if _, answered := control.Provides[door]; !answered {
			control.Provides[door] = answer
		}
	}
	prove.Green(t, s.Checks, control)
}

// A second version check, for the leg idioms the rows above ride. The
// harness's own covers the check format; this one covers what a model row
// does with it. Regenerate the file to clear a mismatch.
var _ = legs.CompatV1

// contractModelRows is what this package's model tier claims.
//
// Every row here needs sequences of calls judged against something
// outside the subject, which is what separates them from the rows
// above: those settle a claim with a fixed call sequence, and these
// cannot be stated that way at all. That is also why each takes the
// Subject rather than an instance — a sequence run builds its own, and
// some of them build two.
func contractModelRows() []suite.Check[Contract] {
	return []suite.Check[Contract]{
		{
			ID:    contractCheckIndex.Model.SingleflightCoalesces(),
			Class: suite.ClassLaws,
			Claim: "concurrent calls for one key compute at most once",
			Binds: []string{
				lawid.SingleflightCoalesces,
			},
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthObserved,
			RunWith: func(tb testing.TB, sub suite.Subject[Contract]) {
				contractAssertSingleflightCoalesces(tb, sub)
			},
		},
		{
			ID:    contractCheckIndex.Model.Counts(),
			Class: suite.ClassLaws,
			Claim: "the subject counts what the reference counts",
			Binds: []string{
				lawid.CountEqualsReference,
			},
			Falsifiable: suite.Argued("no mechanical rule plants a defect for this claim; the ones that would are domain composites, which no rule reaches from shape and stamps alone"),
			Strength:    suite.StrengthObserved,
			RunWith: func(tb testing.TB, sub suite.Subject[Contract]) {
				contractAssertCounts(tb, sub)
			},
		},
	}
}

// --- Contract's model tier -------------------------------------------
//
// Random sequences of Contract's methods, run against every subject and
// something that judges them from outside. The rows on the run surface
// above carry it, and ContractSuite.Without declines any of them by name.
//
//	Reference: the subject's own factory — no reader/writer pair derives a store,
//	           so a second instance driven identically stands in: twins must
//	           agree, which catches nondeterminism and hidden shared state but
//	           not a subject wrong the same way twice; ref= raises the floor
//	Sequences: Flights (aggregator)
//	Not driven:
//	           Run — the annotator classified no shape for it
//
// contractModelActions is the operation vocabulary both legs drive.
//
// One constructor per method shape, from the engine's action set rather
// than hand-written closures: the constructors record inputs and outputs
// into the trace a law reads, compare the two sides the same way for every
// action, and shrink a failing sequence to the shortest one that still
// fails.
func contractModelActions() []model.Action[Contract] {
	return []model.Action[Contract]{
		action.Aggregator("Flights",
			func(ctx context.Context, s singleflight.Contract) (int, error) {
				return s.Flights(ctx)
			}),
	}
}

// contractAssertSingleflightCoalesces binds AUTO-SINGLEFLIGHT-COALESCES over the shared sequences.
//
// One law, and the run's only oracle. The differential is off here, as
// on every law leg: with it armed a subject broken anywhere disagrees at
// step 0, and whether THIS law can catch a defect stays unanswerable.
func contractAssertSingleflightCoalesces(
	tb testing.TB,
	sub suite.Subject[Contract],
) {
	tb.Helper()
	// The inputs pool is the law's own: a wide domain for a stateless
	// claim, which the colliding pair deliberately does not serve.
	inputs := model.Make[string]()
	// The coalescing law's own instrumentation: its compute increments
	// this under the lock, because a subject that fails to coalesce
	// invokes it concurrently.
	coalesceCalls := 0
	var coalesceMu sync.Mutex

	buildRef, tier := legs.Reference(tb, sub, func() Contract { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(),
		[]law.Law[Contract]{
			law.SingleflightCoalesces[singleflight.Contract, string, string]{
				Call: func(ctx context.Context, s singleflight.Contract, k string, compute func() string) (string, error) {
					return s.Run(ctx, k, compute)
				},
				Compute: func() string {
					coalesceMu.Lock()
					coalesceCalls++
					coalesceMu.Unlock()
					var v string
					return v
				},
				Counter: &coalesceCalls,
				Keys:    inputs,
			},
		})
}

// contractAssertCounts binds AUTO-COUNT-EQUALS-REFERENCE over the shared sequences.
//
// One law, and the run's only oracle. The differential is off here, as
// on every law leg: with it armed a subject broken anywhere disagrees at
// step 0, and whether THIS law can catch a defect stays unanswerable.
func contractAssertCounts(
	tb testing.TB,
	sub suite.Subject[Contract],
) {
	tb.Helper()

	buildRef, tier := legs.Reference(tb, sub, func() Contract { return sub.New(tb) })
	sub.NoteTier(tier)
	legs.Law(tb, sub,
		func() Contract { return sub.New(tb) }, buildRef,
		contractModelActions(),
		[]law.Law[Contract]{
			law.CountEqualsReference[singleflight.Contract, int]{
				Count: func(rt *model.T, s singleflight.Contract) (int, error) {
					return s.Flights(rt.Context())
				},
			},
		})
}

// PropT is the property state a Prop body receives: the run's
// draws, and the failure reporting that shrinks a counterexample.
//
// An alias, so it is the engine's own type — this is here only so a
// property you write names PropT rather than obliging your test
// file to import the engine directly.
type PropT = model.T

